const chai = require('chai')

const rotaCarrinhos = '/carrinhos'
const rotaCancelarCompra = `${rotaCarrinhos}/cancelar-compra`
const utils = require('../utils')

describe(rotaCancelarCompra + ' DELETE', () => {
  it('Registro excluído com sucesso. Estoque reabastecido', async () => {
    const { email, password } = await utils.cadastrarUsuario({ administrador: 'true' })
    const { authorization } = await utils.login(email, password)
    const quantidade = utils.quantidadeAleatoria()
    const { _id: idProduto } = await utils.cadastrarProduto({ authorization, quantidade })

    const { body: bodyNovoCarrinho } = await request.post(rotaCarrinhos).set('authorization', authorization).send({
      produtos: [{
        idProduto,
        quantidade: quantidade - utils.SOBRA_NO_ESTOQUE
      }]
    }).expect(201)

    const { _id: idCarrinho } = bodyNovoCarrinho

    const { body: bodyDel } = await request.del(rotaCancelarCompra).set('authorization', authorization).expect(200)
    const { body: bodyProduto } = await request.get('/produtos').query({ _id: idProduto }).expect(200)
    const { body: bodyCarrinho } = await request.get(`${rotaCarrinhos}/${idCarrinho}`)

    chai.assert.deepEqual(bodyDel, { message: 'Registro excluído com sucesso. Estoque dos produtos reabastecido' })
    chai.assert.equal(bodyProduto.produtos[0].quantidade, quantidade)
    chai.assert.deepEqual(bodyCarrinho, { message: 'Carrinho não encontrado' })
  })

  it('Quantidade em texto no carrinho: estoque e quantidadeTotal continuam números até o cancelamento', async () => {
    const { email, password } = await utils.cadastrarUsuario({ administrador: 'true' })
    const { authorization } = await utils.login(email, password)
    const { _id: idProduto } = await utils.cadastrarProduto({ authorization, quantidade: 10 })
    const { _id: idCarrinho } = await utils.cadastrarCarrinho({ idProduto, quantidade: '2', authorization })

    const { body: bodyCarrinho } = await request.get(`${rotaCarrinhos}/${idCarrinho}`).expect(200)
    const { body: bodyProdutoNoCarrinho } = await request.get(`/produtos/${idProduto}`).expect(200)

    chai.assert.strictEqual(bodyCarrinho.quantidadeTotal, 2)
    chai.assert.strictEqual(bodyProdutoNoCarrinho.quantidade, 8)

    await request.del(rotaCancelarCompra).set('authorization', authorization).expect(200)
    const { body: bodyProdutoReabastecido } = await request.get(`/produtos/${idProduto}`).expect(200)

    chai.assert.strictEqual(bodyProdutoReabastecido.quantidade, 10)
  })

  it('Não foi encontrado carrinho para esse usuário', async () => {
    const { email, password } = await utils.cadastrarUsuario({ administrador: 'false' })
    const { authorization } = await utils.login(email, password)
    const { body } = await request
      .del(rotaCancelarCompra)
      .set('authorization', authorization)
      .expect(200)

    chai.assert.deepEqual(body, { message: 'Não foi encontrado carrinho para esse usuário' })
  })

  it('Token ausente', async () => {
    const { body } = await request
      .del(rotaCancelarCompra)
      .expect(401)

    chai.assert.deepEqual(body, {
      message: 'Token de acesso ausente, inválido, expirado ou usuário do token não existe mais'
    })
  })

  it('Token inválido - Apenas Bearer', async () => {
    const { body } = await request
      .del(rotaCancelarCompra)
      .set('authorization', 'Bearer')
      .expect(401)

    chai.assert.deepEqual(body, {
      message: 'Token de acesso ausente, inválido, expirado ou usuário do token não existe mais'
    })
  })

  // Fora do E2E: não deixa produto com estoque extremo nos ambientes compartilhados.
  it('Estoque reabastecido não passa de Number.MAX_SAFE_INTEGER quando o produto foi alterado no meio - @skipE2E', async () => {
    const { email, password } = await utils.cadastrarUsuario({ administrador: 'true' })
    const { authorization } = await utils.login(email, password)
    const produto = await utils.cadastrarProduto({ authorization, quantidade: 10 })
    await utils.cadastrarCarrinho({ idProduto: produto._id, quantidade: 5, authorization })
    const { _id, ...dados } = produto
    await request.put(`/produtos/${_id}`).set('authorization', authorization)
      .send({ ...dados, quantidade: Number.MAX_SAFE_INTEGER }).expect(200)

    await request.del(rotaCancelarCompra).set('authorization', authorization).expect(200)

    const { body } = await request.get('/produtos').query({ _id }).expect(200)
    chai.assert.equal(body.produtos[0].quantidade, Number.MAX_SAFE_INTEGER)
  })

  it('Token inválido - Sem Bearer', async () => {
    const { email, password } = await utils.cadastrarUsuario({ administrador: 'false' })
    const { authorization } = await utils.login(email, password)
    const { body } = await request
      .del(rotaCancelarCompra)
      .set('authorization', authorization.split(' ')[1])
      .expect(401)

    chai.assert.deepEqual(body, {
      message: 'Token de acesso ausente, inválido, expirado ou usuário do token não existe mais'
    })
  })

  it('Token inválido - Usuário excluído', async () => {
    const { email, password, _id } = await utils.cadastrarUsuario({ administrador: 'true' })
    const { authorization } = await utils.login(email, password)
    await request.del(`/usuarios/${_id}`).expect(200)

    const { body } = await request
      .del(rotaCancelarCompra)
      .set('authorization', authorization)
      .expect(401)

    chai.assert.deepEqual(body, {
      message: 'Token de acesso ausente, inválido, expirado ou usuário do token não existe mais'
    })
  })
})

